-- Заполнение библиотеки статей контентом

-- Категория: Питание (nutrition)
INSERT INTO t_p76837068_nikolife_health_app.articles (title, category, content, published_date, view_count) VALUES
('Основы правильного питания: с чего начать', 'nutrition', 'Правильное питание — это не диета, а образ жизни. В этой статье разберем базовые принципы: баланс БЖУ, важность воды, режим приема пищи. Узнаете, как составить здоровый рацион без строгих ограничений и голода. Практические советы помогут сделать первые шаги к здоровому питанию уже сегодня.', '2025-01-15', 342),

('Белок в рационе: сколько нужно и где брать', 'nutrition', 'Белок — строительный материал для мышц и важный элемент здорового метаболизма. Разбираем нормы потребления для разных целей: похудение, набор массы, поддержание формы. Полный список белковых продуктов: животные и растительные источники, сочетания для вегетарианцев.', '2025-01-18', 289),

('Углеводы: простые vs сложные. Что выбрать?', 'nutrition', 'Не все углеводы одинаковы! Простые дают быструю энергию, но провоцируют скачки сахара. Сложные насыщают надолго и поддерживают стабильный уровень энергии. Узнаете, какие углеводы есть до и после тренировки, как они влияют на вес и когда их лучше ограничить.', '2025-01-22', 267),

('Жиры в питании: друзья или враги?', 'nutrition', 'Жиры необходимы для гормонального баланса, усвоения витаминов и здоровья кожи. Разбираем омега-3, омега-6, насыщенные и трансжиры. Какие жиры полезны, сколько их нужно и в каких продуктах искать. Развенчиваем мифы о "вредных" жирах.', '2025-01-25', 301),

('Meal prep: как готовить на неделю вперед', 'nutrition', 'Заготовка еды на неделю экономит время, деньги и помогает держать рацион под контролем. Пошаговый план: выбор рецептов, закупка продуктов, правильное хранение. Идеи для завтраков, обедов и ужинов. Лайфхаки для заморозки и разогрева блюд без потери пользы.', '2025-01-28', 418),

('Водный баланс: сколько пить и почему это важно', 'nutrition', 'Вода участвует во всех процессах организма: пищеварение, терморегуляция, доставка питательных веществ. Индивидуальная норма воды: расчет по весу и активности. Признаки обезвоживания. Как приучить себя пить больше воды: приложения, бутылки с разметкой, напоминания.', '2025-01-23', 356);

-- Категория: Тренировки (training)
INSERT INTO t_p76837068_nikolife_health_app.articles (title, category, content, published_date, view_count) VALUES
('Силовые тренировки для начинающих', 'training', 'Силовые тренировки ускоряют метаболизм, укрепляют кости и формируют красивое тело. Разбираем базовые упражнения: приседания, отжимания, планка. Как составить программу на 3 дня в неделю, избежать травм и правильно восстанавливаться. Тренировки дома и в зале.', '2025-01-16', 523),

('Кардио для жиросжигания: что работает?', 'training', 'HIIT, бег, ходьба, велосипед — какое кардио эффективнее для похудения? Сравниваем интенсивность, расход калорий и влияние на мышцы. Оптимальная частота и продолжительность кардиотренировок. Как совмещать кардио и силовые для максимального результата.', '2025-01-20', 456),

('Растяжка и гибкость: почему это важно', 'training', 'Растяжка улучшает подвижность суставов, снижает риск травм и ускоряет восстановление после тренировок. Виды растяжки: статическая, динамическая, PNF. Комплекс упражнений на все группы мышц. Когда растягиваться: до, после или в отдельный день?', '2025-01-24', 334),

('Тренировки дома без оборудования', 'training', 'Эффективные тренировки не требуют абонемента в зал и дорогого инвентаря. Программа на все тело с собственным весом: упражнения для ног, спины, груди, пресса. Как прогрессировать, увеличивая нагрузку. План на 4 недели для новичков.', '2025-01-27', 612),

('Восстановление после тренировок: ключ к прогрессу', 'training', 'Мышцы растут не на тренировке, а во время отдыха! Разбираем фазы восстановления, роль сна и питания. Активное восстановление: легкое кардио, массаж, контрастный душ. Признаки перетренированности и как их избежать. Оптимальная частота тренировок.', '2025-01-30', 389),

('Йога для здоровья спины и осанки', 'training', 'Сидячий образ жизни приводит к болям в спине и нарушению осанки. Йога помогает укрепить мышечный корсет, улучшить гибкость позвоночника и снять напряжение. Комплекс асан для ежедневной практики: кошка-корова, собака мордой вниз, поза ребенка. Техника безопасности для новичков.', '2025-02-02', 445);

-- Категория: Здоровье (health)
INSERT INTO t_p76837068_nikolife_health_app.articles (title, category, content, published_date, view_count) VALUES
('Иммунитет: как укрепить защитные силы организма', 'health', 'Сильный иммунитет защищает от вирусов и бактерий. Факторы, влияющие на иммунитет: питание, сон, стресс, активность. Витамины и минералы для иммунной системы: C, D, цинк, селен. Закаливание, прогулки на свежем воздухе, режим дня. Когда нужны иммуномодуляторы.', '2025-01-19', 534),

('Метаболизм: как ускорить обмен веществ', 'health', 'Метаболизм определяет, как быстро организм сжигает калории. Факторы влияния: возраст, пол, мышечная масса, гормоны. Как разогнать метаболизм: силовые тренировки, дробное питание, достаточный сон, холодовое воздействие. Мифы о "медленном обмене веществ".', '2025-01-22', 478),

('Гормональный баланс и вес: связь и решения', 'health', 'Гормоны регулируют аппетит, накопление жира и расход энергии. Инсулин, кортизол, лептин, грелин — как они работают. Признаки гормонального дисбаланса. Питание и образ жизни для нормализации гормонов. Когда нужны анализы и консультация эндокринолога.', '2025-01-25', 423),

('Пищеварение: как улучшить работу ЖКТ', 'health', 'Здоровое пищеварение — основа усвоения питательных веществ и хорошего самочувствия. Роль клетчатки, пробиотиков и ферментов. Как избежать вздутия, запоров и тяжести. Режим питания для комфортного пищеварения. Когда дискомфорт — повод обратиться к врачу.', '2025-01-28', 389),

('Витамины и БАДы: что действительно нужно', 'health', 'Нужны ли всем витамины или достаточно питания? Анализы для проверки дефицитов: D, B12, железо, магний. Когда БАДы оправданы: беременность, вегетарианство, дефициты. Как выбрать качественные добавки. Риски передозировки и взаимодействия с лекарствами.', '2025-01-31', 501),

('Здоровый сон: как высыпаться и восстанавливаться', 'health', 'Сон влияет на вес, иммунитет, настроение и продуктивность. Нормы сна для взрослых, фазы и их значение. Как создать идеальные условия: температура, свет, тишина. Ритуалы перед сном, которые помогут засыпать быстрее. Что делать при бессоннице.', '2025-01-17', 487),

('Стресс и здоровье: как управлять эмоциями', 'health', 'Хронический стресс разрушает здоровье: набор веса, проблемы с сердцем, ослабление иммунитета. Разбираем механизмы влияния стресса на организм. Техники управления: дыхательные практики, медитация, физическая активность. Когда стоит обратиться к специалисту.', '2025-01-21', 398);